config.command:
set -eu
umask 077
export LC_ALL=C
base=/workspace/fieldkit
[ -d "$base" ] && [ ! -L "$base" ] || { printf 'Create the fieldkit folder in the sandbox workspace first.\n' >&2; exit 2; }
cd "$base"
need() {
  command -v "$1" >/dev/null 2>&1 || { printf 'Missing command: %s. Install the packages listed in this tool.\n' "$1" >&2; exit 127; }
}
check_file() {
  [ -f "$1" ] && [ ! -L "$1" ] || { printf 'Required regular file missing: %s\n' "$1" >&2; exit 2; }
  bytes=$(wc -c < "$1")
  [ "$bytes" -gt 0 ] && [ "$bytes" -le "$2" ] || { printf 'Input is empty or exceeds this tool size limit.\n' >&2; exit 2; }
}
need ffuf
check_file words.txt 2048
awk 'NR > 20 || length($0) > 64 || $0 !~ /^[A-Za-z0-9_-]+$/ {exit 1} END {if (NR == 0) exit 1}' ./words.txt || { printf 'Use 1-20 simple alphanumeric path names, one per line.\n' >&2; exit 2; }
ffuf -u http://127.0.0.1:8080/FUZZ -w ./words.txt -t 1 -rate 2 -maxtime 20 -timeout 2 -noninteractive -s -json -mc 200,204,301,302,401,403
